  + name : string
  + published : boolean
  + minBallSpeed : float
  + ballSpeedIncreaseFactor : float
  + maxPaddleLength : float
  + minPaddleLength : float
}

class Block {
  + color : string
  + points : int
}

class Level {
  + levelNumber : int
  + isRandom : boolean
  + numberOfBlocks : int
}

