  + score : int
}

class PlayedGame {
  + lives : int
  + currentLevel : int
  + isPaused : boolean
}

class PlayedBall {
  + currentX : float
  + currentY : float
  + currentSpeedX : float
  + currentSpeedY : float
}

class PlayedPaddle {
  + currentX : float
  + currentLength : float
}

Player extends User
Admin extends User

Game "1" *-- "*" Block : contains
Game "1" *-- "1..99" Level : contains
Game "1" *-- "*" HallOfFameEntry : has
Game "1" -- "0..1" Admin : managed by
Game "1" -- "*" PlayedGame : played in

Level "1" *-- "*" BlockAssignment : defines
Level "1" -- "*" Block : uses

PlayedGame "*" -- "1" Game : belongs to
PlayedGame "1" *-- "1" PlayedBall : has
PlayedGame "1" *-- "1" PlayedPaddle : has
PlayedGame "1" *-- "*" BlockAssignment : uses

Player "1" -- "*" PlayedGame : plays
Player "1" -- "*" HallOfFameEntry : competes in

BlockAssignment "*" -- "1" Block : places

@enduml

